<div id="items"><?php $sels=old('product_id',[]);$vids=old('variant_id',[]);$qtys=old('quantity',[]);if(!is_array($sels)||!count($sels)){$sels=[''];$vids=[''];$qtys=[''];} foreach($sels as $i=>$sid): ?><div class="item-row" data-item-row><div class="field"><label>Product</label><select name="product_id[]" required data-product-select data-product-search><option value="">Select product</option><?php foreach($products as $p): ?><option value="<?=$p['id']?>" <?=((string)$sid===(string)$p['id'])?'selected':''?>><?=esc($p['code'].' · '.$p['name'].' · '.$p['unit'])?></option><?php endforeach; ?></select></div><div class="field"><label>Size / Variant</label><select name="variant_id[]" required data-variant-select><option value="">Select product first</option></select></div><div class="field"><label>Quantity</label><input type="number" name="quantity[]" min="1" step="1" value="<?=esc($qtys[$i]??'')?>" required></div><div class="item-stock" data-size-label>—</div><button class="btn icon remove-btn" type="button" data-remove-item>×</button></div><?php endforeach; ?></div></div></div>
