<script>
function variantLabel(v){try{const o=typeof v.attributes_json==='string'?JSON.parse(v.attributes_json||'{}'):(v.attributes_json||{});const parts=Object.entries(o||{}).map(([k,val])=>{const label=k.replace(/[_-]/g,' ').replace(/\b\w/g,c=>c.toUpperCase());if(val&&typeof val==='object'&&Object.prototype.hasOwnProperty.call(val,'value'))return label+': '+val.value+(val.unit?' '+val.unit:'');return label+': '+(typeof val==='object'?JSON.stringify(val):val);});return parts.join(' · ')||v.variant_name||'Default';}catch(e){return v.variant_name||'Variant';}}

const variantMap=<?=json_encode($variantMap??[],JSON_UNESCAPED_UNICODE)?>;const box=document.getElementById('items');const template=box.firstElementChild.outerHTML;const savedVariants=<?=json_encode($vids,JSON_UNESCAPED_UNICODE)?>;
function updateRow(row,saved=''){const s=row.querySelector('[data-product-select]'),vs=row.querySelector('[data-variant-select]'),out=row.querySelector('[data-size-label]');const current=saved||vs.value;const list=Object.values(variantMap).filter(v=>String(v.product_id)===String(s.value));vs.innerHTML='<option value="">Select size / variant</option>'+list.map(v=>'<option value="'+v.id+'" '+(String(v.id)===String(current)?'selected':'')+'>'+variantLabel(v)+'</option>').join('');const v=variantMap[vs.value];out.textContent=v&&v.size_value?('Size · '+Number(v.size_value).toFixed(3)+' '+v.size_unit+' / '+Number(v.size_inches).toFixed(3)+' in'):(v?'Variant selected':'—');}
function bind(row,i=0){row.querySelector('[data-remove-item]')?.addEventListener('click',()=>{if(box.children.length>1)row.remove()});row.querySelector('[data-product-select]').addEventListener('change',()=>updateRow(row));row.querySelector('[data-variant-select]').addEventListener('change',()=>updateRow(row));updateRow(row,savedVariants[i]||'')}
[...box.children].forEach((r,i)=>bind(r,i));document.querySelector('[data-add-item]')?.addEventListener('click',()=>{const d=document.createElement('div');d.innerHTML=template;const r=d.firstElementChild;r.querySelectorAll('input').forEach(i=>i.value='');r.querySelector('[data-product-select]').selectedIndex=0;r.querySelector('[data-variant-select]').innerHTML='<option value="">Select product first</option>';box.appendChild(r);bind(r,0)});
</script>
